{"query": "
-- Count active employees (current salary records)
SELECT COUNT(DISTINCT employee_id) AS active_employees
FROM employees.salary
WHERE to_date = '9999-01-01';
"}

{"query": "
-- Validate department_employee active records
SELECT COUNT(DISTINCT employee_id) AS active_dept_employees
FROM employees.department_employee
WHERE to_date = '9999-01-01';
"}
